<template>
  <q-dialog :model-value="modelValue" @update:model-value="$emit('update:modelValue', $event)">
    <q-card class="min-w-[420px] max-w-[500px] rounded-xl">
      <q-card-section class="flex items-center justify-between p-4">
        <h3 class="text-lg font-semibold">{{ $t('edit_integration') }}</h3>
        <q-btn flat round dense v-close-popup>
          <Icon icon="mdi:close" class="size-4" />
        </q-btn>
      </q-card-section>

      <q-card-section v-if="integration" class="flex flex-col gap-3 p-4 pt-0">
        <!-- Platform info -->
        <div class="flex items-center gap-2 text-sm text-muted-foreground">
          <Icon :icon="platformIcon" class="size-4" />
          <span>{{ integration.platform }} &middot; {{ integration.bot_mode }}</span>
        </div>

        <!-- Name -->
        <q-input
          v-model="form.name"
          :label="$t('name')"
          outlined
          dense
        />

        <!-- Teams custom credentials -->
        <template v-if="integration.platform === 'teams' && integration.bot_mode === 'custom'">
          <q-input
            v-model="form.app_id"
            :label="$t('app_id')"
            outlined
            dense
            :placeholder="$t('credentials_saved')"
          />
          <q-input
            v-model="form.app_secret"
            :label="$t('app_secret')"
            outlined
            dense
            type="password"
            :placeholder="$t('credentials_saved')"
          />
        </template>
      </q-card-section>

      <q-card-actions class="flex items-center justify-between p-4">
        <q-btn
          flat
          dense
          class="text-destructive"
          :loading="deleting"
          @click="confirmDelete"
        >
          <Icon icon="mdi:delete-outline" class="mr-1 size-4" />
          {{ $t('delete') }}
        </q-btn>
        <div class="flex gap-2">
          <q-btn outline dense :label="$t('cancel')" v-close-popup />
          <q-btn
            color="primary"
            dense
            :label="$t('save')"
            :loading="saving"
            @click="save"
          />
        </div>
      </q-card-actions>
    </q-card>
  </q-dialog>

  <!-- Delete confirmation -->
  <q-dialog v-model="deleteConfirmOpen">
    <q-card class="min-w-[360px] rounded-xl">
      <q-card-section class="p-4">
        <h3 class="text-lg font-semibold">{{ $t('delete_integration') }}</h3>
        <p class="mt-2 text-sm text-muted-foreground">
          {{ $t('delete_integration_confirm') }}
        </p>
      </q-card-section>
      <q-card-actions align="right" class="p-4">
        <q-btn outline dense :label="$t('cancel')" v-close-popup />
        <q-btn
          color="negative"
          dense
          :label="$t('delete')"
          :loading="deleting"
          @click="doDelete"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import { notify } from 'src/components/notifications/notify';
import DocNetIntegrationService from 'src/services/docnet/DocNetIntegrationService';
import OperatorApiService from 'src/services/operator/OperatorApiService';
import type { DocNetIntegration } from 'src/@types/docnet';

const operatorService = new OperatorApiService();

const service = new DocNetIntegrationService();

export default defineComponent({
  name: 'IntegrationCredentialDialog',

  components: { Icon },

  props: {
    modelValue: { type: Boolean, default: false },
    integration: {
      type: Object as PropType<DocNetIntegration | null>,
      default: null,
    },
  },

  emits: ['update:modelValue', 'saved', 'deleted'],

  data() {
    return {
      form: {
        name: '',
        app_id: '',
        app_secret: '',
      },
      saving: false,
      deleting: false,
      deleteConfirmOpen: false,
    };
  },

  computed: {
    platformIcon(): string {
      return this.integration?.platform === 'teams'
        ? 'mdi:microsoft-teams'
        : 'mdi:message-text';
    },
  },

  watch: {
    integration: {
      immediate: true,
      handler(val: DocNetIntegration | null) {
        if (val) {
          this.form = {
            name: val.name,
            app_id: '',
            app_secret: '',
          };
        }
      },
    },
  },

  methods: {
    async save() {
      if (!this.integration) return;
      this.saving = true;
      try {
        const payload: Record<string, any> = {};
        if (this.form.name !== this.integration.name) {
          payload.name = this.form.name;
        }
        const credentials: Record<string, string> = {};
        if (this.form.app_id) credentials.app_id = this.form.app_id;
        if (this.form.app_secret) credentials.app_secret = this.form.app_secret;
        if (Object.keys(credentials).length) {
          credentials.api_key = await operatorService.getApiKey();
          payload.credentials = credentials;
        }

        if (!Object.keys(payload).length) {
          this.$emit('update:modelValue', false);
          return;
        }
        await service.updateIntegration(this.integration.id, payload);
        notify.success(this.$t('saved') as string);
        this.$emit('update:modelValue', false);
        this.$emit('saved');
      } catch (e: any) {
        const msg = e?.response?.data?.error || e?.message || this.$t('integration_error_update') as string;
        notify.error(msg);
      } finally {
        this.saving = false;
      }
    },

    confirmDelete() {
      this.deleteConfirmOpen = true;
    },

    async doDelete() {
      if (!this.integration) return;
      this.deleting = true;
      try {
        await service.deleteIntegration(this.integration.id);
        notify.success(this.$t('deleted') as string);
        this.deleteConfirmOpen = false;
        this.$emit('update:modelValue', false);
        this.$emit('deleted');
      } catch (e: any) {
        const msg = e?.response?.data?.error || e?.message || this.$t('integration_error_delete') as string;
        notify.error(msg);
      } finally {
        this.deleting = false;
      }
    },
  },
});
</script>
