    <div class="mb-8">
      <h2 class="m-0 text-2xl font-semibold text-primary">{{ $t('docnet_settings') }}</h2>
      <p class="mt-1 text-sm text-muted-foreground">
        {{ $t('docnet_settings_desc') }}
      </p>
    </div>

    <!-- ─── Main two-column layout ─────────────────────────────── -->
    <div class="grid grid-cols-1 gap-8 lg:grid-cols-2">

      <!-- LEFT: Dashboard Widgets -->
      <section>
        <div class="mb-4">
          <h3 class="m-0 text-base font-semibold text-foreground">{{ $t('dashboard_widgets') }}</h3>
          <p class="mt-0.5 text-xs text-muted-foreground">{{ $t('dashboard_widgets_desc') }}</p>
        </div>

        <div v-for="group in widgetGroups" :key="group.label" class="mb-3">
          <div class="mb-1.5 text-[0.7rem] font-semibold uppercase tracking-wide text-muted-foreground">
            {{ group.label }}
          </div>
          <div class="flex flex-col">
            <div v-for="widget in group.widgets" :key="widget.id" class="setting-widget-row">
              <Icon :icon="widget.icon" width="16" class="shrink-0 text-muted-foreground" />
              <span class="flex-1 truncate text-sm">{{ $t(widget.titleKey) }}</span>
              <q-toggle
                :model-value="isEnabled(widget.id)"
                dense
                size="sm"
                @update:model-value="toggle(widget.id, $event)"
              />
            </div>
          </div>
        </div>

        <transition name="fade">
          <q-btn
            v-if="hasChanges"
            color="primary"
            :label="$t('save')"
            size="sm"
            dense
            :loading="saving"
            class="mt-2"
            @click="saveLayout"
          />
        </transition>
      </section>

      <!-- RIGHT: Integrations -->
      <section>
      <div class="mb-4 flex items-start justify-between gap-2">
        <div class="min-w-0">
          <h3 class="m-0 text-base font-semibold text-foreground">{{ $t('integrations') }}</h3>
          <p class="mt-0.5 text-xs text-muted-foreground">{{ $t('integrations_desc') }}</p>
        </div>
        <q-btn flat round dense size="sm" class="shrink-0">
          <Icon icon="mdi:plus" class="size-5" />
          <q-tooltip>{{ $t('add_integration') }}</q-tooltip>
          <q-menu>
            <q-list dense style="min-width: 220px">
              <q-item clickable v-close-popup @click="startConnectTeams">
                <q-item-section avatar class="min-w-0 pr-2">
                  <Icon icon="mdi:microsoft-teams" class="size-4 text-muted-foreground" />
                </q-item-section>
                <q-item-section>
                  <q-item-label class="text-sm">{{ $t('connect_teams') }}</q-item-label>
                  <q-item-label caption class="text-xs">{{ $t('connect_teams_hint') }}</q-item-label>
                </q-item-section>
              </q-item>
              <q-item clickable v-close-popup @click="startCustomBot">
                <q-item-section avatar class="min-w-0 pr-2">
                  <Icon icon="mdi:microsoft-teams" class="size-4 text-muted-foreground" />
                </q-item-section>
                <q-item-section>
                  <q-item-label class="text-sm">{{ $t('add_custom_bot') }}</q-item-label>
                  <q-item-label caption class="text-xs">{{ $t('add_custom_bot_hint') }}</q-item-label>
                </q-item-section>
              </q-item>
              <q-separator />
              <q-item clickable v-close-popup @click="startConnectDiscord">
                <q-item-section avatar class="min-w-0 pr-2">
                  <Icon icon="mdi:message-text" class="size-4 text-muted-foreground" />
                </q-item-section>
                <q-item-section>
                  <q-item-label class="text-sm">{{ $t('connect_discord') }}</q-item-label>
                  <q-item-label caption class="text-xs">{{ $t('connect_discord_hint') }}</q-item-label>
                </q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </q-btn>
      </div>


      <!-- Loading -->
      <div v-if="integrationStore.loading && !integrationStore.integrations.length" class="py-4">
        <q-skeleton type="rect" height="48px" class="mb-2 rounded-lg" />
        <q-skeleton type="rect" height="48px" class="rounded-lg" />
      </div>

      <!-- Error banner -->
      <div
        v-if="integrationStore.error"
        class="mb-3 flex items-center gap-2 rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive"
      >
        <Icon icon="mdi:alert-circle-outline" class="size-4 shrink-0" />
        <span class="flex-1">{{ integrationStore.error }}</span>
        <q-btn flat round dense size="xs" @click="integrationStore.error = null">
          <Icon icon="mdi:close" class="size-3.5" />
        </q-btn>
      </div>

      <template v-else>
        <!-- Teams -->
        <div v-if="integrationStore.teamsIntegrations.length" class="mb-5">
          <div class="mb-2 flex items-center gap-2">
            <Icon icon="mdi:microsoft-teams" class="size-4 text-muted-foreground" />
            <span class="text-[0.7rem] font-semibold uppercase tracking-wide text-muted-foreground">Microsoft Teams</span>
          </div>
          <div class="flex flex-col gap-2">
            <IntegrationCard
              v-for="integration in integrationStore.teamsIntegrations"
              :key="integration.id"
              :integration="integration"
              :activating="activatingId === integration.id"
              @activate="activateIntegration"
              @edit="openEditDialog"
            />
          </div>
        </div>

        <TeamsConnectFlow ref="teamsFlow" @created="refreshIntegrations" />

        <!-- Discord -->
        <div v-if="integrationStore.discordIntegrations.length" :class="{ 'mt-5': integrationStore.teamsIntegrations.length }">
          <div class="mb-2 flex items-center gap-2">
            <Icon icon="mdi:message-text" class="size-4 text-muted-foreground" />
            <span class="text-[0.7rem] font-semibold uppercase tracking-wide text-muted-foreground">Discord</span>
          </div>
          <div class="flex flex-col gap-2">
            <IntegrationCard
              v-for="integration in integrationStore.discordIntegrations"
              :key="integration.id"
              :integration="integration"
              :activating="activatingId === integration.id"
              @activate="activateIntegration"
              @edit="openEditDialog"
            />
          </div>
        </div>

        <DiscordConnectForm ref="discordForm" @created="refreshIntegrations" />

        <!-- Empty -->
        <div
          v-if="!integrationStore.integrations.length && !integrationStore.loading"
          class="rounded-lg border border-dashed border-border px-4 py-8 text-center"
        >
          <Icon icon="mdi:connection" class="mx-auto mb-2 size-8 text-muted-foreground/40" />
          <p class="m-0 text-sm text-muted-foreground">{{ $t('no_integrations_yet') }}</p>
        </div>
      </template>
    </section>

    </div>
    <!-- end two-column grid -->

    <!-- ─── Demo Data (full width, bottom) ────────────────────── -->
    <div class="mt-8 border-t border-border pt-8">
      <div class="flex items-center justify-between">
        <div>
          <h3 class="m-0 text-base font-semibold text-foreground">{{ $t('demo_data') }}</h3>
          <p class="mt-0.5 text-xs text-muted-foreground">{{ $t('demo_data_desc') }}</p>
        </div>
        <q-toggle
          :model-value="settingsStore.useMockData"
          color="primary"
          @update:model-value="settingsStore.toggleMockData()"
        />
      </div>
    </div>

    <!-- Credential/Edit dialog -->
    <IntegrationCredentialDialog
      v-model="editDialogOpen"
      :integration="editingIntegration"
      @saved="refreshIntegrations"
      @deleted="refreshIntegrations"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useDocNetSettingsStore } from 'src/store/DocNet/docnet-settings.store';
import { useDocNetDashboardStore } from 'src/store/DocNet/docnet-dashboard.store';
import { useDocNetIntegrationStore } from 'src/store/DocNet/docnet-integrations.store';
import { WIDGET_CATALOG } from '../Dashboard/widgets/registry';
import { Icon } from '@iconify/vue';
import type { DocNetWidgetId, DocNetDashboardLayout, DocNetIntegration } from 'src/@types/docnet';
import type { WidgetMeta } from '../Dashboard/widgets/registry';
import IntegrationCard from './components/IntegrationCard.vue';
import TeamsConnectFlow from './components/TeamsConnectFlow.vue';
import DiscordConnectForm from './components/DiscordConnectForm.vue';
import IntegrationCredentialDialog from './components/IntegrationCredentialDialog.vue';

const CATEGORY_LABEL_KEYS: Record<string, string> = {
  fleet: 'widget_category_fleet',
  kpi: 'widget_category_kpi',
  chart: 'widget_category_charts',
  list: 'widget_category_lists',
};

const CATEGORY_ORDER = ['fleet', 'kpi', 'chart', 'list'];

export default defineComponent({
  name: 'DocNetSettings',

  components: {
    Icon,
    IntegrationCard,
    TeamsConnectFlow,
    DiscordConnectForm,
    IntegrationCredentialDialog,
  },

  setup() {
    const settingsStore = useDocNetSettingsStore();
    const integrationStore = useDocNetIntegrationStore();
    return { settingsStore, integrationStore };
  },

  data() {
    return {
      pendingEnabled: [] as DocNetWidgetId[],
      saving: false,
      initialized: false,
      editDialogOpen: false,
      editingIntegration: null as DocNetIntegration | null,
      activatingId: null as string | null,
    };
  },

  computed: {
    dashboardStore() {
      return useDocNetDashboardStore();
    },

    widgetGroups(): Array<{ label: string; widgets: WidgetMeta[] }> {
      const groups: Record<string, WidgetMeta[]> = {};
      WIDGET_CATALOG.forEach((w) => {
        if (!groups[w.category]) groups[w.category] = [];
        groups[w.category].push(w);
      });
      return CATEGORY_ORDER
        .filter((cat) => groups[cat]?.length)
        .map((cat) => ({
          label: this.$t(CATEGORY_LABEL_KEYS[cat] || cat) as string,
          widgets: groups[cat],
        }));
    },

    hasChanges(): boolean {
      if (!this.initialized) return false;
      const current = new Set(this.dashboardStore.layout.enabled_widgets);
      const pending = new Set(this.pendingEnabled);
      if (current.size !== pending.size) return true;
      for (const id of current) {
        if (!pending.has(id)) return true;
      }
      return false;
    },
  },

  async mounted() {
    await this.dashboardStore.loadLayout();
    this.pendingEnabled = [...this.dashboardStore.layout.enabled_widgets];
    this.initialized = true;
    this.integrationStore.fetchIntegrations();
  },

  methods: {
    isEnabled(id: DocNetWidgetId): boolean {
      return this.pendingEnabled.includes(id);
    },

    toggle(id: DocNetWidgetId, enabled: boolean) {
      if (enabled) {
        if (!this.pendingEnabled.includes(id)) {
          this.pendingEnabled.push(id);
        }
      } else {
        this.pendingEnabled = this.pendingEnabled.filter((x) => x !== id);
      }
    },

    async saveLayout() {
      this.saving = true;
      try {
        const newLayout: DocNetDashboardLayout = {
          version: this.dashboardStore.layout.version,
          enabled_widgets: this.pendingEnabled,
        };
        await this.dashboardStore.saveLayout(newLayout);
      } finally {
        this.saving = false;
      }
    },

    async activateIntegration(integration: DocNetIntegration) {
      this.activatingId = integration.id;
      try {
        await this.integrationStore.toggleIntegration(integration.id, true);
      } finally {
        this.activatingId = null;
      }
    },

    openEditDialog(integration: DocNetIntegration) {
      this.editingIntegration = integration;
      this.editDialogOpen = true;
    },

    startConnectTeams() {
      (this.$refs.teamsFlow as InstanceType<typeof TeamsConnectFlow>)?.generateCode();
    },

    startCustomBot() {
      (this.$refs.teamsFlow as InstanceType<typeof TeamsConnectFlow>)?.showCustomBotForm();
    },

    startConnectDiscord() {
      (this.$refs.discordForm as InstanceType<typeof DiscordConnectForm>)?.show();
    },

    refreshIntegrations() {
      this.integrationStore.fetchIntegrations();
    },
  },
});
</script>

