<template>
  <div v-if="connectState !== 'idle' || showCustomForm" class="flex flex-col gap-4">
    <div v-if="connectState === 'loading'" class="flex items-center gap-2 text-sm text-muted-foreground">
      <q-spinner size="16px" />
      {{ $t('generating_code') }}
    </div>

    <!-- Code display + countdown -->
    <div v-if="connectState === 'code'" class="rounded-xl border p-4">
      <div class="mb-2 text-sm text-muted-foreground">
        {{ $t('connect_teams_instruction') }}
      </div>
      <div class="mb-3 flex items-center gap-3">
        <code class="rounded-lg bg-muted px-4 py-2 text-xl font-bold tracking-widest">
          {{ connectCode }}
        </code>
        <q-btn flat round dense size="sm" @click="copyCode">
          <Icon icon="mdi:content-copy" class="size-4" />
        </q-btn>
      </div>
      <div class="flex items-center gap-2 text-xs text-muted-foreground">
        <Icon icon="mdi:clock-outline" class="size-3.5" />
        <span>{{ $t('expires_in') }} {{ countdownDisplay }}</span>
      </div>
      <div class="mt-2 flex items-center gap-2 text-xs text-muted-foreground">
        <q-spinner size="12px" />
        {{ $t('waiting_for_connection') }}
      </div>
    </div>

    <!-- Connected success -->
    <div v-if="connectState === 'connected'" class="flex items-center gap-2 text-sm text-success">
      <Icon icon="mdi:check-circle-outline" class="size-5" />
      {{ $t('teams_connected') }}
    </div>

    <!-- Expired -->
    <div v-if="connectState === 'expired'" class="flex items-center gap-2 text-sm text-warning">
      <Icon icon="mdi:clock-alert-outline" class="size-5" />
      {{ $t('connect_code_expired') }}
      <q-btn flat dense size="sm" :label="$t('retry')" @click="generateCode" />
    </div>

    <!-- Custom bot form (collapsible) -->
    <div v-if="showCustomForm && connectState === 'idle'" class="rounded-xl border p-4">
      <div class="mb-3 text-sm font-medium">{{ $t('custom_bot_setup') }}</div>
      <div class="flex flex-col gap-3">
        <q-input
          v-model="customForm.name"
          :label="$t('name')"
          outlined
          dense
        />
        <q-input
          v-model="customForm.platform_id"
          :label="$t('tenant_id')"
          outlined
          dense
          :hint="$t('azure_tenant_id_hint')"
        />
        <q-input
          v-model="customForm.app_id"
          :label="$t('app_id')"
          outlined
          dense
        />
        <q-input
          v-model="customForm.app_secret"
          :label="$t('app_secret')"
          outlined
          dense
          type="password"
        />
        <div class="flex justify-end gap-2">
          <q-btn outline dense :label="$t('cancel')" @click="showCustomForm = false" />
          <q-btn
            color="primary"
            dense
            :label="$t('create')"
            :loading="customSubmitting"
            :disable="!customFormValid"
            @click="submitCustomBot"
          />
        </div>
      </div>
    </div>

  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import { copyToClipboard, Notify } from 'quasar';
import DocNetIntegrationService from 'src/services/docnet/DocNetIntegrationService';
import { useDocNetIntegrationStore } from 'src/store/DocNet/docnet-integrations.store';
import OperatorApiService from 'src/services/operator/OperatorApiService';

const operatorService = new OperatorApiService();

const service = new DocNetIntegrationService();

export default defineComponent({
  name: 'TeamsConnectFlow',

  components: { Icon },

  emits: ['created'],

  data() {
    return {
      connectState: 'idle' as 'idle' | 'loading' | 'code' | 'connected' | 'expired',
      connectCode: '',
      countdownSeconds: 0,
      countdownTimer: null as ReturnType<typeof setInterval> | null,
      pollTimer: null as ReturnType<typeof setInterval> | null,
      initialIntegrationIds: new Set<string>(),
      showCustomForm: false,
      customSubmitting: false,
      customForm: {
        name: '',
        platform_id: '',
        app_id: '',
        app_secret: '',
      },
    };
  },

  computed: {
    countdownDisplay(): string {
      const m = Math.floor(this.countdownSeconds / 60);
      const s = this.countdownSeconds % 60;
      return `${m}:${String(s).padStart(2, '0')}`;
    },
    customFormValid(): boolean {
      const f = this.customForm;
      return !!(f.name && f.platform_id && f.app_id && f.app_secret);
    },
  },

  beforeUnmount() {
    this.clearTimers();
  },

  methods: {
    async generateCode() {
      this.showCustomForm = false;
      this.connectState = 'loading';
      try {
        const store = useDocNetIntegrationStore();
        this.initialIntegrationIds = new Set(
          store.teamsIntegrations.map((i) => i.id),
        );
        const result = await service.generateTeamsConnectCode();
        this.connectCode = result.code;
        this.countdownSeconds = result.expires_in_seconds;
        this.connectState = 'code';
        this.startCountdown();
        this.startPolling();
      } catch (e: any) {
        Notify.create({ type: 'negative', message: e?.response?.data?.error || e?.message || this.$t('integration_error_generate_code') as string, position: 'top' });
        this.connectState = 'idle';
      }
    },

    startCountdown() {
      this.countdownTimer = setInterval(() => {
        this.countdownSeconds--;
        if (this.countdownSeconds <= 0) {
          this.clearTimers();
          this.connectState = 'expired';
          Notify.create({ type: 'warning', message: this.$t('connect_code_expired') as string, position: 'top' });
        }
      }, 1000);
    },

    startPolling() {
      const store = useDocNetIntegrationStore();
      this.pollTimer = setInterval(async () => {
        await store.fetchIntegrations();
        const newIntegration = store.teamsIntegrations.find(
          (i) => !this.initialIntegrationIds.has(i.id),
        );
        if (newIntegration) {
          this.clearTimers();
          this.connectState = 'connected';
          this.$emit('created');
        }
      }, 5000);
    },

    clearTimers() {
      if (this.countdownTimer) {
        clearInterval(this.countdownTimer);
        this.countdownTimer = null;
      }
      if (this.pollTimer) {
        clearInterval(this.pollTimer);
        this.pollTimer = null;
      }
    },

    copyCode() {
      copyToClipboard(this.connectCode)
        .then(() => Notify.create({ type: 'positive', message: this.$t('copied') as string, position: 'top' }))
        .catch(() => Notify.create({ type: 'negative', message: this.$t('copy_failed') as string, position: 'top' }));
    },

    resetConnectFlow() {
      this.connectState = 'idle';
      this.connectCode = '';
      this.countdownSeconds = 0;
      this.showCustomForm = false;
    },

    showCustomBotForm() {
      this.resetConnectFlow();
      this.showCustomForm = true;
    },

    async submitCustomBot() {
      this.customSubmitting = true;
      try {
        const apiKey = await operatorService.getApiKey();
        await service.createIntegration({
          platform: 'teams',
          platform_id: this.customForm.platform_id,
          name: this.customForm.name,
          bot_mode: 'custom',
          credentials: {
            app_id: this.customForm.app_id,
            app_secret: this.customForm.app_secret,
            api_key: apiKey,
          },
        });
        this.showCustomForm = false;
        this.customForm = { name: '', platform_id: '', app_id: '', app_secret: '' };
        this.$emit('created');
      } catch (e: any) {
        Notify.create({ type: 'negative', message: e?.response?.data?.error || e?.message || this.$t('integration_error_create') as string, position: 'top' });
      } finally {
        this.customSubmitting = false;
      }
    },
  },
});
</script>
