import { defineStore } from 'pinia';
import DocNetIntegrationService from 'src/services/docnet/DocNetIntegrationService';
import type { DocNetIntegration } from 'src/@types/docnet';

const service = new DocNetIntegrationService();

export const useDocNetIntegrationStore = defineStore('docnet_integrations', {
  state: () => ({
    integrations: [] as DocNetIntegration[],
    loading: false,
    error: null as string | null,
    _fetchPromise: null as Promise<void> | null,
  }),

  getters: {
    teamsIntegrations: (state) =>
      state.integrations.filter((i) => i.platform === 'teams'),
    discordIntegrations: (state) =>
      state.integrations.filter((i) => i.platform === 'discord'),
    activeTeams: (state) =>
      state.integrations.find(
        (i) => i.platform === 'teams' && i.is_enabled,
      ) || null,
    activeDiscord: (state) =>
      state.integrations.find(
        (i) => i.platform === 'discord' && i.is_enabled,
      ) || null,
  },

  actions: {
    async fetchIntegrations() {
      if (this._fetchPromise) return this._fetchPromise;

      this.loading = true;
      this.error = null;
      this._fetchPromise = service
        .getIntegrations()
        .then((result) => {
          this.integrations = result;
        })
        .catch((e: any) => {
          this.error = e?.message || 'Failed to load integrations';
        })
        .finally(() => {
          this.loading = false;
          this._fetchPromise = null;
        });

      return this._fetchPromise;
    },

    async toggleIntegration(id: string, isEnabled: boolean) {
      this.error = null;
      try {
        await service.toggleIntegration(id, isEnabled);
        await this.fetchIntegrations();
      } catch (e: any) {
        this.error = e?.message || 'Failed to toggle integration';
      }
    },

    async deleteIntegration(id: string) {
      this.error = null;
      try {
        await service.deleteIntegration(id);
        await this.fetchIntegrations();
      } catch (e: any) {
        this.error = e?.message || 'Failed to delete integration';
      }
    },
  },
});
