<template>
  <div v-if="showForm" class="flex flex-col gap-4">
    <div class="rounded-xl border p-4">
      <div class="mb-3 text-sm font-medium">{{ $t('connect_discord') }}</div>
      <div class="flex flex-col gap-3">
        <!-- Bot invite link -->
        <div v-if="discordBotInviteUrl" class="rounded-lg border border-border bg-muted/30 p-3">
          <p class="m-0 mb-2 text-xs text-muted-foreground">
            {{ $t('discord_invite_hint') }}
          </p>
          <a
            :href="discordBotInviteUrl"
            target="_blank"
            rel="noopener noreferrer"
            class="inline-flex items-center gap-1.5 text-sm font-medium text-primary hover:underline"
          >
            <Icon icon="mdi:open-in-new" class="size-4" />
            {{ $t('discord_add_bot') }}
          </a>
        </div>
        <q-input
          v-model="form.name"
          :label="$t('name')"
          outlined
          dense
        />
        <q-input
          v-model="form.platform_id"
          :label="$t('guild_id')"
          outlined
          dense
          :hint="$t('discord_guild_id_hint')"
        />
        <div class="flex justify-end gap-2">
          <q-btn outline dense :label="$t('cancel')" @click="showForm = false" />
          <q-btn
            color="primary"
            dense
            :label="$t('create')"
            :loading="submitting"
            :disable="!formValid"
            @click="submit"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Notify } from 'quasar';
import { Icon } from '@iconify/vue';
import DocNetIntegrationService from 'src/services/docnet/DocNetIntegrationService';
import OperatorApiService from 'src/services/operator/OperatorApiService';
import { DISCORD_BOT_INVITE_URL } from 'src/pages/APIs';

const operatorService = new OperatorApiService();
const service = new DocNetIntegrationService();

export default defineComponent({
  name: 'DiscordConnectForm',

  components: { Icon },

  emits: ['created'],

  data() {
    return {
      showForm: false,
      submitting: false,
      form: {
        name: '',
        platform_id: '',
      },
    };
  },

  computed: {
    formValid(): boolean {
      return !!(this.form.name && this.form.platform_id);
    },
    discordBotInviteUrl(): string {
      return DISCORD_BOT_INVITE_URL;
    },
  },

  methods: {
    show() {
      this.showForm = true;
    },

    async submit() {
      this.submitting = true;
      try {
        const apiKey = await operatorService.getApiKey();
        await service.createIntegration({
          platform: 'discord',
          platform_id: this.form.platform_id,
          name: this.form.name,
          bot_mode: 'shared',
          credentials: {
            api_key: apiKey,
          },
        });
        Notify.create({ type: 'positive', message: this.$t('discord_connected') as string, position: 'top' });
        this.showForm = false;
        this.form = { name: '', platform_id: '' };
        this.$emit('created');
      } catch (e: any) {
        const msg = e?.response?.data?.error || e?.message || this.$t('integration_error_create') as string;
        Notify.create({ type: 'negative', message: msg, position: 'top' });
      } finally {
        this.submitting = false;
      }
    },
  },
});
</script>
