<template>
  <div
    class="flex items-center gap-3 rounded-lg border px-3 py-2.5 transition-colors"
    :class="integration.is_enabled
      ? 'border-success/30 bg-success/5'
      : 'border-border bg-background hover:bg-muted/30'"
  >
    <!-- Active indicator dot -->
    <span
      class="size-2 shrink-0 rounded-full"
      :class="integration.is_enabled ? 'bg-success' : 'bg-muted-foreground/30'"
    />

    <!-- Name + bot mode -->
    <div class="flex min-w-0 flex-1 items-center gap-2">
      <span class="truncate text-sm font-medium text-foreground">{{ integration.name }}</span>
      <span
        class="shrink-0 rounded border px-1.5 py-0.5 text-[10px] font-medium leading-none"
        :class="integration.bot_mode === 'custom'
          ? 'border-warning/40 bg-warning/10 text-warning'
          : 'border-primary/40 bg-primary/10 text-primary'"
      >
        {{ $t('bot_mode_' + integration.bot_mode) }}
      </span>
    </div>

    <!-- Active label or Activate button -->
    <span
      v-if="integration.is_enabled"
      class="shrink-0 text-xs font-medium text-success"
    >
      {{ $t('active') }}
    </span>
    <q-btn
      v-else
      outline
      dense
      size="sm"
      :label="$t('activate')"
      :loading="activating"
      class="shrink-0"
      @click="$emit('activate', integration)"
    />

    <!-- Gear button -->
    <q-btn flat round dense size="sm" @click="$emit('edit', integration)">
      <Icon icon="mdi:cog" class="size-4 text-muted-foreground" />
    </q-btn>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { Icon } from '@iconify/vue';
import type { DocNetIntegration } from 'src/@types/docnet';

export default defineComponent({
  name: 'IntegrationCard',

  components: { Icon },

  props: {
    integration: {
      type: Object as PropType<DocNetIntegration>,
      required: true,
    },
    activating: {
      type: Boolean,
      default: false,
    },
  },

  emits: ['activate', 'edit'],
});
</script>
